import numpy as np
from solution import (compute_cubical_persistent_homology_2d, pd0_summary,
                      iaaft_reference, surrogate_quality, rank_match)


def test_pd0_matches_shipped_diagram_with_plateaus_and_boundaries():
    rng = np.random.default_rng(842)
    for x in (rng.normal(size=(12, 13)), rng.integers(0, 6, (9, 11)).astype(float)):
        pd, _ = compute_cubical_persistent_homology_2d(x, periodic=False)
        life = pd[:-1, 1] - pd[:-1, 0]
        assert np.allclose(pd0_summary(x), [len(life), sum(life)], atol=1e-12)


def test_monotonic_rank_remapping_preserves_component_count():
    rng = np.random.default_rng(17)
    x, target = rng.normal(size=(14, 15)), rng.exponential(size=(14, 15))
    h = rank_match(x, target)
    assert np.array_equal(np.sort(h.ravel()), np.sort(target.ravel()))
    assert pd0_summary(x)[0] == pd0_summary(h)[0]


def test_projection_preserves_exact_stage_constraints():
    rng = np.random.default_rng(92)
    x = rng.normal(size=(16, 16))
    initial = rng.permutation(x.ravel()).reshape(x.shape)
    s, h = iaaft_reference(x, initial, 60)
    q = surrogate_quality(s, h, x)
    assert q["spectrum_stage_relative_error"] < 1e-12
    assert q["histogram_stage_exact"]
    assert pd0_summary(s)[0] == pd0_summary(h)[0]
    assert q["histogram_stage_spectrum_error"] < .1


def test_invalid_fields_rejected():
    for x in (np.ones((5, 5)), np.array([[0., 1.], [2., np.nan]])):
        try:
            pd0_summary(x)
        except ValueError:
            continue
        raise AssertionError("invalid field accepted")


