def test_recorded_cuda_fft_and_ranks_recomputed_in_float64():
    rng = np.random.default_rng(GPU_ATTESTATION["seed"])
    target = rng.normal(size=(16, 16))
    initial = rng.permutation(target.ravel()).reshape(target.shape)
    spectrum, histogram = iaaft_reference(target, initial, 1)
    device_s = np.asarray(GPU_ATTESTATION["spectrum"])
    device_h = np.asarray(GPU_ATTESTATION["histogram"])
    assert device_s.shape == device_h.shape == (16, 16)
    assert np.allclose(device_s, spectrum, rtol=1e-11, atol=1e-11)
    assert np.array_equal(device_h, histogram)
    assert surrogate_quality(device_s, device_h, target)["spectrum_stage_relative_error"] < 1e-12
